function noise2d = generate_correlated_noise_fft_Lc(X_km, Y_km, Lc_km, target_std)
%GENERATE_CORRELATED_NOISE_FFT_LC  Spatially correlated Gaussian noise generated by FFT filtering.
%
%   noise2d = generate_correlated_noise_fft_Lc(X_km, Y_km, Lc_km, target_std)
%
%   A white Gaussian random field is filtered in the frequency domain with the
%   isotropic Lorentzian power spectrum (Supporting Information Text S1,
%   Equations S2-S3)
%
%       S(f) = 1 / (1 + (f * Lc)^2),
%
%   where f is the radial spatial frequency (cycles/km). The result is
%   normalized to zero mean and unit standard deviation and then scaled to
%   target_std. A larger Lc gives smoother noise. When Lc is larger than the
%   grid (Lc = 500 km for the 400 x 400 km grid used in this study), S(f)
%   follows an approximately power-law (red) decay, S(f) ~ f^-2, over the
%   resolved wavelengths.
%
%   INPUTS
%     X_km, Y_km - coordinate grids (km) from meshgrid, regular spacing
%     Lc_km      - correlation length scale Lc (km)
%     target_std - standard deviation of the output noise (e.g., mm/yr)
%
%   OUTPUT
%     noise2d    - correlated noise, same size as X_km
%
%   The current state of the random number generator is used; call rng()
%   beforehand for reproducible noise.

    [ny, nx] = size(X_km);

    % Grid spacing (km)
    dx = abs(mean(diff(X_km(1, :))));
    dy = abs(mean(diff(Y_km(:, 1))));

    % Frequency coordinates (cycles/km), in FFT order
    kx = ifftshift((0:nx-1) - floor(nx/2));
    ky = ifftshift((0:ny-1) - floor(ny/2));
    [KX, KY] = meshgrid(kx, ky);
    freq = sqrt((KX ./ (nx * dx)).^2 + (KY ./ (ny * dy)).^2);

    % Lorentzian power spectrum and corresponding amplitude spectrum
    S = 1 ./ (1 + (freq * Lc_km).^2);
    A = sqrt(S);

    % Filter a white Gaussian random field in the frequency domain
    white = randn(ny, nx);
    y = real(ifft2(fft2(white) .* A));

    % Normalize to zero mean and scale to the target standard deviation
    y = y - mean(y(:));
    y = y ./ std(y(:));
    noise2d = y * target_std;

end
